3	const INSURANCE_VALUES: Record<string, number> = {
4	  sword: 1000,
5	  amulet: 600,
6	  staff: 800,
7	  potion: 400,
8	};
9	const COMPONENT_INSURANCE_VALUE = 250;
10	const CAP_MULTIPLIER = 2;
11	
12	const itemInsuranceValue = (item: Item): number =>
13	  INSURANCE_VALUES[item.type] ?? COMPONENT_INSURANCE_VALUE;
14	
15	const insuranceSum = (items: Item[]): number =>
16	  items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
17	
18	export interface Damage {
19	  itemType: string;
20	  amount: number;
21	}
22	
23	export interface PayoutResult {
24	  payout: number;
25	  remainingCap: number;
26	}
27	
28	const DEDUCTIBLE = 100;
29	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
30	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
31	
32	const reimbursementAmount = (item: Item, damageAmount: number): number => {
33	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD) {
34	    return damageAmount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
35	  }
36	  return damageAmount;
37	};
38	
39	export const calculatePayout = (
40	  policyItems: Item[],
41	  damages: Damage[],
42	  capRemaining: number = insuranceSum(policyItems) * CAP_MULTIPLIER,
43	): PayoutResult => {
44	  const availableItems = [...policyItems];
45	  const payout = damages.reduce((sum, damage) => {
46	    if (damage.amount < 0) {
47	      throw new Error(`Damage amount must not be negative: ${damage.amount}`);
48	    }
49	    const index = availableItems.findIndex((i) => i.type === damage.itemType);
50	    if (index === -1) {
51	      throw new Error(
52	        `Damage references item type "${damage.itemType}" not covered by the policy`,
53	      );
54	    }
55	    const [item] = availableItems.splice(index, 1);
56	    return sum + reimbursementAmount(item, damage.amount) - DEDUCTIBLE;
57	  }, 0);
58	  const cappedPayout = Math.floor(Math.min(payout, capRemaining));
59	  return { payout: cappedPayout, remainingCap: capRemaining - cappedPayout };
60	};
