16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	};
22	
23	const COMPONENT_BASE_PREMIUM = 25;
24	const COMPONENT_BLOCK_SIZE = 3;
25	const COMPONENT_BLOCK_PREMIUM = 60;
26	
27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
29	
30	const isMainItem = (item: Item): boolean => item.type in BASE_PREMIUMS;
31	
32	const componentsBasePremium = (components: Item[]): number => {
33	  const countsByType = new Map<string, number>();
34	  for (const component of components) {
35	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
36	  }
37	  let total = 0;
38	  for (const count of countsByType.values()) {
39	    total +=
40	      count === COMPONENT_BLOCK_SIZE
41	        ? COMPONENT_BLOCK_PREMIUM
42	        : count * COMPONENT_BASE_PREMIUM;
43	  }
44	  return total;
45	};
46	
47	const CURSED_SURCHARGE_RATE = 0.5;
48	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
49	const HIGH_ENCHANTMENT_THRESHOLD = 5;
50	
51	const itemBasePremium = (item: Item): number =>
52	  BASE_PREMIUMS[item.type] ?? COMPONENT_BASE_PREMIUM;
53	
54	const itemModifiersSurcharge = (item: Item, base: number): number => {
55	  let surcharge = 0;
56	  if (item.cursed) surcharge += base * CURSED_SURCHARGE_RATE;
57	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
58	    surcharge += base * HIGH_ENCHANTMENT_SURCHARGE_RATE;
59	  }
60	  return surcharge;
61	};
62	
63	const calculateBasePremium = (items: Item[]): number => {
64	  const mainItems = items.filter(isMainItem);
65	  const components = items.filter((item) => !isMainItem(item));
66	  const mainItemsPremium = mainItems.reduce(
67	    (sum, item) => sum + itemBasePremium(item),
68	    0,
69	  );
70	  return mainItemsPremium + componentsBasePremium(components);
71	};
72	
73	const calculateItemModifiersSurcharge = (items: Item[]): number =>
74	  items.reduce(
75	    (sum, item) => sum + itemModifiersSurcharge(item, itemBasePremium(item)),
76	    0,
77	  );
