79	export const calculatePremium = (
80	  customer: Customer,
81	  items: Item[],
82	  isFirstContract: boolean,
83	): number => {
84	  const basePremium = calculateBasePremium(items);
85	  const itemModifiers = calculateItemModifiersSurcharge(items);
86	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
87	  const loyaltyDiscount =
88	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
89	      ? basePremium * LOYALTY_DISCOUNT_RATE
90	      : 0;
91	  const followUpContractDiscount = isFirstContract
92	    ? 0
93	    : basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE;
94	  return Math.ceil(
95	    basePremium +
96	      itemModifiers +
97	      firstInsuranceSurcharge -
98	      loyaltyDiscount -
99	      followUpContractDiscount +
100	      PROCESSING_FEE,
101	  );
102	};
